#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_SIZE 10000

int radix = 255;
long range = 1;
long fraction = 0;
int cc[2000000];
unsigned char output_buffer[100000];
int output_pos = 0;

void put_byte(int b) {
    output_buffer[output_pos++] = (unsigned char)b;
}

void put_bit(int bit, int ctx) {
    // Normalize when range gets too large
    while (range >= radix * radix * radix) {
        int byte_val = (fraction / (radix * radix)) + 1;
        put_byte(byte_val);
        fraction = (fraction % (radix * radix)) * radix;
        range /= radix;
    }

    int *counts = cc + ctx * 2;
    long split = range * (counts[0] + 1) / (counts[0] + counts[1] + 2);

    if (bit) {
        fraction += split;
        range -= split;
    } else {
        range = split;
    }

    counts[bit]++;
}

void put_integer(int value, int width, int ctx) {
    value += (1 << width);
    ctx *= 99;

    // Calculate bit length
    int bit_len = 0;
    int temp = value;
    while (temp > 0) {
        bit_len++;
        temp >>= 1;
    }

    // Unary encode the bit length
    for (int i = 0; i < bit_len; i++) {
        put_bit(0, width + 1 + i + ctx);
    }
    put_bit(1, width + 1 + bit_len + ctx);

    // Encode the actual value
    for (int i = bit_len - 1; i >= 0; i--) {
        int bit = (value >> i) & 1;
        put_bit(bit, ctx);
    }
}

void flush_encoder() {
    // Flush remaining bits
    for (int i = 0; i < 3; i++) {
        int byte_val = (fraction / (radix * radix)) + 1;
        put_byte(byte_val);
        fraction = (fraction % (radix * radix)) * radix;
    }
}

typedef struct {
    char type; // 'L' for literal, 'C' for copy
    int val1;  // char value for literal, offset for copy
    int val2;  // unused for literal, length for copy
} Command;

Command commands[MAX_SIZE];
int num_commands = 0;

void find_match(unsigned char *data, int pos, int len, int *best_offset, int *best_len) {
    *best_len = 0;
    *best_offset = 0;

    int max_offset = (1 << 5) - 1;  // OFF1=5, so max offset is 31
    int max_match = (1 << 2) + 1;   // OFF2=2, so max length is 4

    int start = (pos > max_offset) ? (pos - max_offset) : 0;

    for (int i = start; i < pos; i++) {
        int match_len = 0;
        while (match_len < max_match && pos + match_len < len && 
               data[i + match_len] == data[pos + match_len]) {
            match_len++;
        }

        if (match_len > *best_len) {
            *best_len = match_len;
            *best_offset = pos - i - 1;
        }
    }
}

int main() {
    FILE *f = fopen("/app/data.txt", "r");
    if (!f) {
        fprintf(stderr, "Cannot open data.txt\n");
        return 1;
    }

    // Read input
    unsigned char data[MAX_SIZE];
    int data_len = fread(data, 1, MAX_SIZE, f);
    fclose(f);

    // Generate commands
    int pos = 0;
    while (pos < data_len) {
        int offset, length;
        find_match(data, pos, data_len, &offset, &length);

        if (length >= 2) {
            commands[num_commands].type = 'C';
            commands[num_commands].val1 = offset;
            commands[num_commands].val2 = length;
            num_commands++;
            pos += length;
        } else {
            int char_val = (int)data[pos];
            if (char_val > 127) {
                char_val = char_val - 256;
            }
            commands[num_commands].type = 'L';
            commands[num_commands].val1 = char_val;
            num_commands++;
            pos++;
        }
    }

    // Encode
    put_integer(num_commands, 9, 0);

    for (int i = 0; i < num_commands; i++) {
        if (commands[i].type == 'C') {
            put_bit(1, 1);
            put_integer(commands[i].val1, 5, 2);
            put_integer(commands[i].val2 - 1, 2, 3);
        } else {
            put_bit(0, 1);
            int val = commands[i].val1;
            if (val < 0) {
                put_bit(1, 8);
                val = -val;
            } else {
                put_bit(0, 8);
            }
            put_integer(val, 4, 9);
        }
    }

    flush_encoder();

    // Write output
    f = fopen("/app/data.comp", "wb");
    fwrite(output_buffer, 1, output_pos, f);
    fclose(f);

    fprintf(stderr, "Original: %d bytes\n", data_len);
    fprintf(stderr, "Compressed: %d bytes\n", output_pos);
    fprintf(stderr, "Commands: %d\n", num_commands);

    return 0;
}

