}

void encode_bit(int bit, int ctx) {
    int *counts = enc.cc + ctx * 2;
    long range = enc.high - enc.low + 1;
    long total = counts[0] + counts[1] + 2;
    long split = enc.low + (range * (counts[0] + 1)) / total;

    if (bit) {
        enc.low = split;
    } else {
        enc.high = split - 1;
    }

    counts[bit]++;

