    while (((enc.low ^ enc.high) & 0xFF000000) == 0) {
        output_byte((enc.low >> 24) & 0xFF);
        enc.low = (enc.low << 8) & 0xFFFFFFFF;
        enc.high = ((enc.high << 8) & 0xFFFFFFFF) | 0xFF;
