    // Handle underflow
    while ((enc.low & 0x80000000) && !(enc.high & 0x80000000)) {
        enc.pending_bytes++;
        enc.low = (enc.low << 8) & 0x7FFFFFFF;
        enc.high = ((enc.high << 8) | 0xFF) & 0xFFFFFFFF;
        enc.high |= 0x80000000;
