        // Compute byte that will give us a fraction in the target range
        // fraction_after = target_fraction_base + (byte - 1)
        // We want: target_frac_min <= target_fraction_base + (byte - 1) <= target_frac_max
        // So: byte = target_frac_min - target_fraction_base + 1 (minimum valid byte)

